_SIGNATURE_KEYS = ("tables", "columns", "constraints", "indexes", "triggers")

CATALOG_INSPECTION_SQL = "WITH timeout_setting AS (\n    SELECT set_config('statement_timeout', '2000', true)\n), owned_tables AS (\n    SELECT unnest(CAST(:owned_tables AS text[])) AS table_name\n)\nSELECT\n    (SELECT version_num FROM alembic_version LIMIT 1) AS alembic_revision,\n    (SELECT value FROM schema_metadata WHERE key = 'platform_revision') AS schema_revision,\n    (SELECT value FROM schema_metadata WHERE key = 'platform_catalog_fingerprint') AS stored_fingerprint,\n    ARRAY(\n        SELECT format('%s|%s|%s', relations.relname, relations.relkind, relations.relpersistence)\n        FROM pg_class AS relations\n        JOIN pg_namespace AS namespaces ON namespaces.oid = relations.relnamespace\n        JOIN owned_tables ON owned_tables.table_name = relations.relname\n        WHERE namespaces.nspname = current_schema() AND relations.relkind IN ('r', 'p')\n        ORDER BY relations.relname\n    ) AS tables,\n    ARRAY(\n        SELECT format(\n            '%s|%s|%s|%s|%s|%s|%s|%s',\n            relations.relname,\n            attributes.attnum,\n            attributes.attname,\n            format_type(attributes.atttypid, attributes.atttypmod),\n            attributes.attnotnull,\n            COALESCE(pg_get_expr(defaults.adbin, defaults.adrelid, true), ''),\n            attributes.attidentity,\n            attributes.attgenerated\n        )\n        FROM pg_attribute AS attributes\n        JOIN pg_class AS relations ON relations.oid = attributes.attrelid\n        JOIN pg_namespace AS namespaces ON namespaces.oid = relations.relnamespace\n        JOIN owned_tables ON owned_tables.table_name = relations.relname\n        LEFT JOIN pg_attrdef AS defaults\n            ON defaults.adrelid = attributes.attrelid AND defaults.adnum = attributes.attnum\n        WHERE namespaces.nspname = current_schema()\n            AND attributes.attnum > 0\n            AND NOT attributes.attisdropped\n        ORDER BY relations.relname, attributes.attnum\n    ) AS columns,\n    ARRAY(\n        SELECT format(\n            '%s|%s|%s|%s',\n            relations.relname,\n            constraints.conname,\n            constraints.contype,\n            pg_get_constraintdef(constraints.oid, true)\n        )\n        FROM pg_constraint AS constraints\n        JOIN pg_class AS relations ON relations.oid = constraints.conrelid\n        JOIN pg_namespace AS namespaces ON namespaces.oid = relations.relnamespace\n        JOIN owned_tables ON owned_tables.table_name = relations.relname\n        WHERE namespaces.nspname = current_schema()\n        ORDER BY relations.relname, constraints.conname\n    ) AS constraints,\n    ARRAY(\n        SELECT format(\n            '%s|%s|%s',\n            relations.relname,\n            index_relations.relname,\n            pg_get_indexdef(indexes.indexrelid, 0, true)\n        )\n        FROM pg_index AS indexes\n        JOIN pg_class AS relations ON relations.oid = indexes.indrelid\n        JOIN pg_class AS index_relations ON index_relations.oid = indexes.indexrelid\n        JOIN pg_namespace AS namespaces ON namespaces.oid = relations.relnamespace\n        JOIN owned_tables ON owned_tables.table_name = relations.relname\n        WHERE namespaces.nspname = current_schema()\n        ORDER BY relations.relname, index_relations.relname\n    ) AS indexes,\n    ARRAY(\n        SELECT format(\n            '%s|%s|%s',\n            relations.relname,\n            triggers.tgname,\n            pg_get_triggerdef(triggers.oid, true)\n        )\n        FROM pg_trigger AS triggers\n        JOIN pg_class AS relations ON relations.oid = triggers.tgrelid\n        JOIN pg_namespace AS namespaces ON namespaces.oid = relations.relnamespace\n        JOIN owned_tables ON owned_tables.table_name = relations.relname\n        WHERE namespaces.nspname = current_schema() AND NOT triggers.tgisinternal\n        ORDER BY relations.relname, triggers.tgname\n    ) AS triggers\nFROM timeout_setting"

