OWNED_TABLES = tuple(entry.split("|", 1)[0] for entry in EXPECTED_CATALOG_SIGNATURE["tables"])


def catalog_signature_from_row(row: Mapping[str, Any]) -> dict[str, tuple[str, ...]]:
    return {key: tuple(row[key] or ()) for key in _SIGNATURE_KEYS}


def catalog_fingerprint(signature: Mapping[str, Sequence[str]]) -> str:
    payload = {key: list(signature[key]) for key in _SIGNATURE_KEYS}
    serialized = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return hashlib.sha256(serialized).hexdigest()


EXPECTED_CATALOG_FINGERPRINT = catalog_fingerprint(EXPECTED_CATALOG_SIGNATURE)
